-- ============================================================
-- NEON://DIARY — 建库第 2 步：图片（由 db/make-bootstrap.js 生成）
-- ------------------------------------------------------------
-- 只含**被文章引用到**的图片：#2
-- ⚠ 本文件较大（base64），故不进版本库；换环境时现跑生成器即可。
-- ============================================================

-- #2  image/png  1280x720  1508 KB
insert into post_images (id, owner_id, content_type, data, thumb, width, height, size_bytes, created_at) values (
  2, $neon$legacy-import$neon$, $neon$image/png$neon$,
  $neon$$neon$,
  null, 1280, 720, 1543802, $neon$2026-09-28T01:23:18.580824+08:00$neon$::timestamptz
) on conflict (id) do update set owner_id = excluded.owner_id, content_type = excluded.content_type,
  data = excluded.data, thumb = excluded.thumb, width = excluded.width, height = excluded.height,
  size_bytes = excluded.size_bytes, created_at = excluded.created_at;

select setval(pg_get_serial_sequence('post_images','id'), coalesce((select max(id) from post_images), 1));
select '文章 ' || (select count(*) from posts) || ' 篇 / 图片 ' || (select count(*) from public_images) || ' 张' as 建库结果;